import numpy as np
from scipy import ndimage
x=np.load('source_pixels.npz')['rgb'].astype(int)
# Adj diffs threshold max channel > n
for th in [2,5,10,20,40]:
 print('\\nTH',th)
 for t in range(1,96):
  d=np.max(abs(x[t]-x[t-1]),2)>th
  lab,n=ndimage.label(d, structure=np.ones((3,3)))
  comps=[]
  for i in range(1,n+1):
   ys,xs=np.where(lab==i); sz=len(xs)
   if sz>=2: comps.append((sz,xs.min(),ys.min(),xs.max(),ys.max(),round(xs.mean(),1),round(ys.mean(),1)))
  comps.sort(reverse=True)
  if t<15 or t%5==0 or not comps:
   print(t,d.sum(),comps[:4])
# temporal std masks and max change
std=x.std(0).max(2)
for th in [1,2,5,10,20,40]:
 d=std>th; lab,n=ndimage.label(d,np.ones((3,3))); comps=[]
 for i in range(1,n+1):
  yy,xx=np.where(lab==i)
  if len(xx)>=2: comps.append((len(xx),xx.min(),yy.min(),xx.max(),yy.max(),round(xx.mean(),1),round(yy.mean(),1)))
 print('std',th,d.sum(),sorted(comps,reverse=True)[:10])
